namespace ProformaViewer.Services;public static class PageSpecParser{public static IReadOnlyList<int> Parse(string value){if(string.IsNullOrWhiteSpace(value))throw new FormatException("Page is blank.");var p=new List<int>();foreach(var raw in value.Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)){var t=raw.Trim();var x=t.IndexOf('x',StringComparison.OrdinalIgnoreCase);if(x>0){var page=N(t[..x]);var count=N(t[(x+1)..]);for(var i=0;i<count;i++)p.Add(page);}else p.Add(N(t));}return p.Count>0?p:throw new FormatException("Invalid page value.");}static int N(string s)=>int.TryParse(s.Trim(),out var n)&&n>0?n:throw new FormatException($"Invalid page number '{s}'.");}